body.script:
//

(function(){
var NEWSLETTER_URL=''; /* cole aqui o endereço do seu serviço (ex.: https://formspree.io/f/SEU_ID) */
var NOTICIAS_POR_COLUNA=1;
var IC_CLOCK='<svg class="mn-i" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>',IC_COMMENT='<svg class="mn-i" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M21 11.5a8.4 8.4 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.4 8.4 0 0 1-3.8-.9L3 21l1.9-5.7a8.4 8.4 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.4 8.4 0 0 1 3.8-.9h.5a8.5 8.5 0 0 1 8 8z"/></svg>';
function $(s,c){return (c||document).querySelector(s);}
function $$(s,c){return Array.prototype.slice.call((c||document).querySelectorAll(s));}
function pad(n){return n<10?'0'+n:''+n;}
var DIAS=['Domingo','Segunda-feira','Terça-feira','Quarta-feira','Quinta-feira','Sexta-feira','Sábado'];
var MESES=['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];
var D3=['Dom','Seg','Ter','Qua','Qui','Sex','S\u00E1b'],M3=['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'];
function tick(){var d=new Date(),a=$('#mn-date'),b=$('#mn-clock'),sh=$('#mn-date-s');
 if(sh)sh.textContent=D3[d.getDay()]+', '+d.getDate()+' '+M3[d.getMonth()]+' '+d.getFullYear();
 if(a)a.textContent=DIAS[d.getDay()]+', '+d.getDate()+' de '+MESES[d.getMonth()]+' de '+d.getFullYear();
 if(b)b.textContent=pad(d.getHours())+':'+pad(d.getMinutes());}
tick();setInterval(tick,20000);
var y=$('#mn-year');if(y)y.textContent=new Date().getFullYear();
/* tempo */
function wico(c){if(c===0)return '\u2600\uFE0F';if(c<=2)return '\uD83C\uDF24\uFE0F';if(c===3)return '\u2601\uFE0F';if(c===45||c===48)return '\uD83C\uDF2B\uFE0F';if(c>=95)return '\u26C8\uFE0F';if(c>=71&&c<=77)return '\uD83C\uDF28\uFE0F';return '\uD83C\uDF27\uFE0F';}
function weather(v){var p=v.split(','),t=$('#mn-temp'),i=$('#mn-wico');if(!t)return;
 fetch('https://api.open-meteo.com/v1/forecast?latitude='+p[0]+'&longitude='+p[1]+'&current=temperature_2m,weather_code&timezone=auto')
 .then(function(r){return r.json();}).then(function(j){var c=j.current;t.textContent=Math.round(c.temperature_2m)+'\u00B0C';if(i)i.textContent=wico(c.weather_code);})
 .catch(function(){t.textContent='--\u00B0C';});}
var sel=$('#mn-city'),DEF={lat:-25.9692,lon:32.5732,name:'Maputo'};
function autoLabel(n){var o=sel&&sel.querySelector('option[value=auto]');if(o)o.textContent='\uD83D\uDCCD '+(n||'A minha localiza\u00E7\u00E3o');}
function rn(v){return Math.round(v*100)/100;}
function revName(lat,lon){return fetch('https://api.bigdatacloud.net/data/reverse-geocode-client?latitude='+lat+'&longitude='+lon+'&localityLanguage=pt').then(function(r){return r.json();}).then(function(j){return j.city||j.locality||j.principalSubdivision||'';});}
function byIP(){return fetch('https://api.bigdatacloud.net/data/reverse-geocode-client?localityLanguage=pt').then(function(r){return r.json();}).then(function(j){
 if(typeof j.latitude!=='number')throw 0;return {lat:rn(j.latitude),lon:rn(j.longitude),name:j.city||j.locality||j.principalSubdivision||''};});}
function byGPS(){return new Promise(function(ok,no){if(!navigator.geolocation)return no();
 navigator.geolocation.getCurrentPosition(function(p){var l={lat:rn(p.coords.latitude),lon:rn(p.coords.longitude),name:''};
  revName(l.lat,l.lon).then(function(n){l.name=n;ok(l);}).catch(function(){ok(l);});},no,{timeout:8000,maximumAge:600000});});}
function cached(){try{var c=JSON.parse(localStorage.getItem('mn-loc')||'null');if(c&&Date.now()-c.t<3600000)return c;}catch(e){}return null;}
function keep(l){try{localStorage.setItem('mn-loc',JSON.stringify({lat:l.lat,lon:l.lon,name:l.name,t:Date.now()}));}catch(e){}}
function useLoc(l){autoLabel(l.name);weather(l.lat+','+l.lon);}
function auto(){var c=cached();if(c){useLoc(c);return;}autoLabel('A detetar\u2026');
 byGPS().catch(function(){return byIP();}).then(function(l){keep(l);useLoc(l);}).catch(function(){useLoc(DEF);});}
if(sel){var sv=null;try{sv=localStorage.getItem('mn-city');}catch(e){}
 if(sv&&sv!=='auto'&&sel.querySelector('option[value="'+sv+'"]')){sel.value=sv;weather(sv);}else{sel.value='auto';auto();}
 sel.addEventListener('change',function(){try{localStorage.setItem('mn-city',sel.value);}catch(e){}
  if(sel.value==='auto'){try{localStorage.removeItem('mn-loc');}catch(e){}auto();}else weather(sel.value);});}
/* pesquisa */
var box=$('#mn-search'),inp=box&&$('input',box);
function openS(o){if(!box)return;box.classList.toggle('open',o);$$('.mn-open-search').forEach(function(b){b.setAttribute('aria-expanded',o?'true':'false');});if(o&&inp)inp.focus();}
$$('.mn-open-search').forEach(function(b){b.addEventListener('click',function(){openS(!box.classList.contains('open'));});});
var cl=box&&$('.close',box);if(cl)cl.addEventListener('click',function(){openS(false);});
document.addEventListener('keydown',function(e){if(e.key==='Escape')openS(false);});
/* item activo do menu */
(function(){var p=decodeURIComponent(location.pathname);
 $$('.mn-nav>a').forEach(function(a){var h=a.getAttribute('href')||'';if(h.indexOf('/search/label/')===0&&decodeURIComponent(h)===p)a.classList.add('active');});})();
/* tempo relativo e colunas por categoria (feeds do Blogger) */
function ago(iso){var t=new Date(iso).getTime();if(isNaN(t))return '';var s=Math.max(0,(Date.now()-t)/1000);
 if(s<3600){var m=Math.max(1,Math.round(s/60));return 'Há '+m+(m===1?' minuto':' minutos');}
 if(s<86400){var h=Math.round(s/3600);return 'Há '+h+(h===1?' hora':' horas');}
 if(s<604800){var d=Math.round(s/86400);return 'Há '+d+(d===1?' dia':' dias');}
 var D=new Date(t);return pad(D.getDate())+'/'+pad(D.getMonth()+1)+'/'+D.getFullYear();}
function key(u){return (u||'').replace(/^https?:\/\//,'').replace(/[?#].*$/,'').replace(/\/$/,'');}
function alt(e){var l=e.link||[];for(var i=0;i<l.length;i++){if(l[i].rel==='alternate')return l[i].href;}return '';}
function getJ(u){return fetch(u).then(function(r){if(!r.ok)throw 0;return r.json();});}
function dom(h){return new DOMParser().parseFromString(h||'','text/html');}
function dd(t){t=(t||'').replace(/\s+/g,' ').trim();var m=t.match(/^(.{6,}?)\s*\1$/);return m?m[1]:t;}
function cut(x,n){x=(x||'').replace(/\s+/g,' ').trim();return x.length>n?x.slice(0,n-3).replace(/\s+\S*$/,'')+'\u2026':x;}
function info(html){var d=dom(html);$$('style,script,noscript,svg',d).forEach(function(n){n.parentNode.removeChild(n);});
 var h=d.querySelector('h1,.art-title,h2'),t=h?h.textContent.replace(/\s+/g,' ').trim():'';
 var b=(d.body?d.body.textContent:'').replace(/\s+/g,' ').trim();
 if(t&&b.indexOf(t)===0)b=b.slice(t.length).trim();
 return {t:t,s:b};}
function body(e){return e.content?e.content.$t:(e.summary?e.summary.$t:'');}
function mk(tag,cls,txt){var e=document.createElement(tag);if(cls)e.className=cls;if(txt!=null)e.textContent=txt;return e;}
var els=$$('.mn-ago[data-url]'),tels=$$('a.mn-t[data-url]');
tels.forEach(function(a){var x=a.textContent,y=dd(x);if(x&&y!==x.trim())a.textContent=y;});
function setSnip(a,s){var box=a.closest('.mn-hero-main,.mn-card');if(!box||!s||$('.mn-snip',box))return;
 var h=a.parentNode,sn=mk('div','mn-snip',cut(s,140));h.parentNode.insertBefore(sn,h.nextSibling);}
if(els.length||tels.length){getJ('/feeds/posts/summary?alt=json&max-results=150').then(function(j){var m={},t={};
 (j.feed.entry||[]).forEach(function(e){var k=key(alt(e));m[k]=e.published.$t;t[k]=(e.title&&e.title.$t)||'';});
 els.forEach(function(el){var v=m[key(el.getAttribute('data-url'))];if(v){el.textContent=ago(v);el.setAttribute('datetime',v);}});
 var need=[];
 tels.forEach(function(a){var v=t[key(a.getAttribute('data-url'))];if(v)a.textContent=dd(v);else need.push(a);});
 if(!need.length)return;
 return getJ('/feeds/posts/default?alt=json&max-results=40').then(function(j2){var c={};
  (j2.feed.entry||[]).forEach(function(e){c[key(alt(e))]=info(body(e));});
  need.forEach(function(a){var r=c[key(a.getAttribute('data-url'))];if(!r)return;
   var tt=dd(r.t)||cut(r.s,90);if(tt)a.textContent=tt;setSnip(a,r.s);});});}).catch(function(){});}
function fill(card,e){var bd=$('.mn-card-body',card),url=alt(e);bd.innerHTML='';
 var inf=info(body(e)),tt=dd((e.title&&e.title.$t)||inf.t)||cut(inf.s,90);
 var th=e['media$thumbnail'];
 if(th&&th.url){var a=mk('a','mn-thumb');a.href=url;a.tabIndex=-1;var im=new Image();im.loading='lazy';im.alt='';
  im.src=th.url.replace(/\/s\d+(-c)?\//,'/w640-h360-c/').replace(/=s\d+(-c)?$/,'=w640-h360-c');a.appendChild(im);card.insertBefore(a,bd);}
 var h=mk('h3'),l=mk('a',null,tt);l.href=url;h.appendChild(l);bd.appendChild(h);
 var sn=cut(inf.s,115);if(sn)bd.appendChild(mk('div','mn-snip',sn));
 var n=e['thr$total']?e['thr$total'].$t:'0',m=mk('div','mn-meta');
 var s1=mk('span','mn-ico');s1.innerHTML=IC_CLOCK;s1.appendChild(mk('span',null,ago(e.published.$t)));
 var s2=mk('span','mn-ico');s2.innerHTML=IC_COMMENT;s2.appendChild(mk('span',null,n));
 m.appendChild(s1);m.appendChild(mk('span','mn-sep','|'));m.appendChild(s2);bd.appendChild(m);
 var r=mk('a','mn-read-more','Ler mais \u279C');r.href=url;bd.appendChild(r);}
$$('.mn-card[data-label]').forEach(function(card){var lb=card.getAttribute('data-label');
 getJ('/feeds/posts/default/-/'+encodeURIComponent(lb)+'?alt=json&max-results='+NOTICIAS_POR_COLUNA).then(function(j){var e=(j.feed.entry||[])[0];
  if(e)fill(card,e);else $('.mn-card-body',card).innerHTML='<p class="mn-empty">Ainda não há notícias nesta categoria.</p>';})
 .catch(function(){$('.mn-card-body',card).innerHTML='<p class="mn-empty">Não foi possível carregar esta categoria.</p>';});});
/* newsletter */
var nf=$('#mn-newsform');
if(nf){nf.addEventListener('submit',function(ev){ev.preventDefault();var msg=$('#mn-newsmsg');
 if(!NEWSLETTER_URL){msg.textContent='A newsletter ainda não está configurada neste blog.';return;}
 fetch(NEWSLETTER_URL,{method:'POST',body:new FormData(nf),headers:{'Accept':'application/json'}})
 .then(function(r){if(!r.ok)throw 0;msg.textContent='Obrigado! A sua inscrição foi registada.';nf.reset();})
 .catch(function(){msg.textContent='Não foi possível inscrever agora. Tente novamente mais tarde.';});});}
/* seletor de idiomas: encaixa no menu, antes da lupa */
var P=['position:static','top:auto','left:auto','right:auto','bottom:auto','margin:0','transform:none','float:none'];
function place(){var w=$('.mn-tools .gtranslate_wrapper');if(!w)return;
 var f=$('.gt_switcher_wrapper');if(f&&f.parentNode!==w)w.appendChild(f);
 if(f){P.forEach(function(s){var k=s.split(':');f.style.setProperty(k[0],k[1],'important');});}
 if(!w.getAttribute('data-b')&&$('.gt_selected',w)){w.setAttribute('data-b','1');
  var pos=function(){var o=$('.gt_option',w);if(!o)return;var r=w.getBoundingClientRect(),wd=Math.min(170,window.innerWidth-16),l=Math.max(8,Math.min(r.right-wd,window.innerWidth-wd-8));
   o.style.setProperty('top',(r.bottom+4)+'px','important');o.style.setProperty('left',l+'px','important');o.style.setProperty('right','auto','important');o.style.setProperty('width',wd+'px','important');};
  w.addEventListener('click',function(){pos();setTimeout(pos,0);setTimeout(pos,80);},true);
  window.addEventListener('scroll',pos,{passive:true});window.addEventListener('resize',pos);}}
var n=0,t=setInterval(function(){place();if(++n>60)clearInterval(t);},250);
window.addEventListener('load',place);
})();

//
